import React, { useState, useEffect } from 'react';
import Plot from 'react-plotly.js';
import { getTopicLabel } from './topic-labels.js';


const colormap = {'鹿島建設株式会社':'rgb(229, 134, 6)', "株式会社大林組":'rgb(93, 105, 177)', "清水建設株式会社":'rgb(82, 188, 163)',
  "大成建設株式会社":'rgb(153, 201, 69)', "株式会社竹中工務店":'rgb(204, 97, 176)', "株式会社長谷工コーポレーション":'rgb(36, 121, 108)', 
  "前田建設工業株式会社":'rgb(218, 165, 27)',"五洋建設株式会社":'rgb(47, 138, 196)', "株式会社フジタ":'rgb(118, 78, 159)', 
  "戸田建設株式会社":'rgb(237, 100, 90)', "株式会社熊谷組":'rgb(165, 170, 153)'};

// データをロードする関数
const loadCompanies = async (dataPath) => {
  try {
    const response = await fetch(dataPath);
    const text = await response.text();
    return text.split("\n").filter((line) => line.trim() !== "");
  } catch (error) {
    console.error("データの読み込みエラー:", error);
    return [];
  }
};

const toList = async (dataPath) => {
  try {
    const response = await fetch(dataPath);
    const text = await response.text();
    const lines = text.split("\n").filter(line => line.trim() !== "");

    const alpha_li = lines.map(line => parseFloat(line.split(",")[0]));
    const beta_li = lines.map(line => parseFloat(line.split(",")[1]));

    return { alpha_li, beta_li };
  } catch (error) {
    console.error("データの読み込みエラー:", error);
    return { alpha_li: [], beta_li: [] };
  }
};

const PlotPersonTopic = ({ update, visualType, topic, company, onRendered, onClickData, topicLabelMap }) => {
  const arrow_color = ['#E24E42', '#E9B000', '#EB6E80', '#9B7EDE', '#63D2FF'];
  const [figData, setFigData] = useState([]);
  const [annotations, setAnnotations] = useState([]);
  const [companyList, setCompanyList] = useState([]);
  const [searchList, setSearchList] = useState([]);
  const [title, setTitle] = useState("");
  const [authorData, setAuthorData] = useState({});

  // 初期データのロード
  useEffect(() => {
    if (visualType === "one-topic" && topic) {
      const target_id = topic; // トピックIDの設定
      const columnPath = `${process.env.PUBLIC_URL}/data/visualize_data/topic${target_id}/span=3/setting/company.txt`;

      loadCompanies(columnPath).then((data) => {
        setCompanyList(data);
        setTitle(`${getTopicLabel(target_id, topicLabelMap)}: 業界内での企業の立ち位置`);
      });
    }
  }, [visualType, topic, topicLabelMap]);

  // 検索対象のフィルタリング
  useEffect(() => {
    if (companyList.length > 0) {
      const companyDict = companyList.reduce((acc, value, idx) => {
        acc[value] = idx;
        return acc;
      }, {});

      const newSearchList = Array.isArray(company) ? company : [company];
      setSearchList(newSearchList.filter(value => value in companyDict));
    }
  }, [companyList, company]);

  // 著者データをロードする新しいuseEffect
  useEffect(() => {
    const loadAuthorData = async () => {
      if (Array.isArray(company) && company.includes("株式会社熊谷組") || company === "株式会社熊谷組") {
        try {
          const authorPath = `${process.env.PUBLIC_URL}/data/visualize_data/topic${topic}/span=3/persona/kumagai_topic_author.json`;
          const response = await fetch(authorPath);
          if (!response.ok) {
            throw new Error(`著者データの読み込みに失敗: ${response.status}`);
          }
          const data = await response.json();
          
          // 年度とペルソナの対応マップ
          const yearToPersona = {
            "2021": "1",
            "2019": "2",
            "2017": "3",
            "2015": "4",
            "2013": "5"
          };
          
          // 各ペルソナのデータを整形
          const personaData = {};
          Object.entries(yearToPersona).forEach(([year, personaNum]) => {
            const yearData = data[year] || {};
            
            // 空のオブジェクトかどうかをチェック
            if (Object.keys(yearData).length === 0) {
              personaData[`persona_${personaNum}`] = {
                authors: '出願者なし',
                year: year
              };
            } else {
              // データがある場合は上位5件を取得
              const topAuthors = Object.entries(yearData)
                .slice(0, 5)
                .map(([author, count]) => `${author}(${count}件)`);
              
              personaData[`persona_${personaNum}`] = {
                authors: topAuthors.join(', '),
                year: year
              };
            }
          });
          
          setAuthorData(personaData);
        } catch (error) {
          console.error("著者データの読み込みエラー:", error);
        }
      }
    };

    loadAuthorData();
  }, [company, topic]);

  // データの描画
  useEffect(() => {
    if ((update || figData.length === 0) && searchList.length > 0 && topic) {
      const target_id = topic; // トピックIDの設定
      const node_alpha = Array.from({ length: searchList.length }, () => Array(5).fill(0));
      const node_beta = Array.from({ length: searchList.length }, () => Array(5).fill(0));

      const promises = Array.from({ length: 5 }, (_, i) => i ).map((p) => {
        const parameterPath = `${process.env.PUBLIC_URL}/data/visualize_data/topic${target_id}/span=3/persona/test_optimize_${p+1}.txt`;
        return toList(parameterPath).then(({ alpha_li, beta_li }) => {
          searchList.forEach((k, j) => {
            const idx = companyList.indexOf(k);
            node_alpha[j][p] = alpha_li[idx];
            node_beta[j][p] = beta_li[idx];
          });
        });
      });

      Promise.all(promises).then(() => {
        const personaToYear = {
          "5": "2021",
          "4": "2018",
          "3": "2015",
          "2": "2012",
          "1": "2009"
        };

        const plotData = searchList.map((k, j) => {
          const hoverTexts = ["1", "2", "3", "4", "5"].map((num) => {
            const yearText = `${personaToYear[num]}`;
            const year = parseInt(yearText);  // 文字列を数値に変換
            if (k === "株式会社熊谷組" && authorData[`persona_${num}`]) {
              return `(${year-3}~${year})<br>著者: ${authorData[`persona_${num}`].authors}`;
            }
            return `(${year-3}~${year})`;
          });

          return {
            x: node_alpha[j],
            y: node_beta[j],
            mode: "lines+markers+text",
            text: ["1", "2", "3", "4", "5"],
            textposition: "top left",
            hovertext: hoverTexts,
            hoverinfo: "text",
            hoverlabel: {
              align: 'left',
              bgcolor: 'white',
              bordercolor: 'gray',
              font: { size: 12 },
              xanchor: 'right',  // ホバーのx位置
              yanchor: 'bottom'     // ホバーのy位置
            },
            marker: {
              symbol: 'circle',
              color: colormap[k],
              size: 5,
            },
            name: k,
          };
        });

        const plotAnnotations = searchList.flatMap((k, j) =>
          Array(4).fill(0).map((_, i) => ({
            x: node_alpha[j][i + 1],
            y: node_beta[j][i + 1],
            xref: 'x',
            yref: 'y',
            ax: node_alpha[j][i],
            ay: node_beta[j][i],
            axref: 'x',
            ayref: 'y',
            arrowcolor: colormap[k],
            arrowsize: 1.2,
            arrowwidth: 1.2,
            arrowhead: 5,
            showarrow: true,
          }))
        );

        setFigData(plotData);
        setAnnotations(plotAnnotations);
        if (onRendered) onRendered();
      });
    }
  }, [update, searchList, companyList, topic, authorData, figData.length]);

  const handlePersonaClick = (event) => {
    if (event.points && event.points[0]) {
    
      console.log(event.points[0]["data"]["name"])
      const clickdata = event.points[0]["data"]["name"]; // クリックされた部分のラベル
      onClickData([clickdata]); // 親コンポーネントにラベルを通知
    }
  };

  return (
    <div  style={{ width:'100vh' ,height: '100vh' }}>
      <Plot
        data={figData}
        layout={{
          plot_bgcolor: 'white',
          paper_bgcolor: 'white',
          annotations: annotations,
          title: {
            text: title,
            font: { size: 20, color: 'black' },
      
            x: 0.5,
            y: 0.95,
            xanchor: 'center',
          
          },
          annotations: [
            {
              x: 0.5,
              y: 1.8,
              text: '（業界を引っ張り伝統的な分野に取り組んでいる）',
              showarrow: false,
              font: { size: 9, color: 'gray' },
              xanchor: 'center',
              yanchor: 'middle',
            },
            {
              x: 1.5,
              y: 1.8,
              text: '（業界を引っ張り未知の分野に投資している）',
              showarrow: false,
              font: { size: 9, color: 'gray' },
              xanchor: 'center',
              yanchor: 'middle',
            },
            {
              x: 0.5,
              y: 0.2,
              text: '（独自路線を進み伝統的な分野に取り組んでいる）',
              showarrow: false,
              font: { size: 9, color: 'gray' },
              xanchor: 'center',
              yanchor: 'middle',
            },
            {
              x: 1.5,
              y: 0.2,
              text: '（独自路線を進み未知の分野に投資している）',
              showarrow: false,
              font: { size: 9, color: 'gray' },
              xanchor: 'center',
              yanchor: 'middle',
            },
          ],

         
          xaxis: {
            title : "新規性",
            range: [0.1, 1.9],
            linecolor: 'gray',
            linewidth: 1,
            gridcolor: 'lightgrey',
            gridwidth: 1,
            griddash: 'dot',
            tickmode:"array",
            tickvals:[0.1, 1, 1.9],
            ticktext:["低", "", "高"],
            zeroline: false,

          },
          yaxis: {
            title : "順応性",
            title_standoff:25,   // Y軸からの距離（見やすくするため）
            range: [0.1, 1.9],
            linecolor: 'gray',
            linewidth: 1,
            gridcolor: 'lightgrey',
            gridwidth: 1,
            griddash: 'dot',
            tickmode:"array",
            tickvals:[0.1, 1, 1.9],
            ticktext:["低", "", "高"],
            zeroline: false,

          },
          margin: { t: 25, b: 15, l: 15, r: 20 },
          showlegend: true,
          legend: {
            x: 1,
            y: 1,
            bgcolor: 'rgba(255,255,255,0.5)',
            bordercolor: 'gray',
            borderwidth: 1,
          },
          hoverdistance: 50,
          hovermode: 'closest',
          hoverlabel: {
            namelength: -1
          },
        }}
        config={{ 
          responsive: true,
          displayModeBar: false
        }}
        style={{marginTop:"2vh", width: "100vh", height: "45vh" }}
        onClick={handlePersonaClick}
      />
    </div>
  );
};

export default PlotPersonTopic;
